demos.code:
thee add(a, b) {
    kanal a + b
}

thee is_even(n) {
    endral n % 2 == 0 {
        kanal unmai
    } illai {
        kanal poi
    }
}

thee list_total(numbers) {
    na total = 0
    ozhugu number ul numbers {
        total = total + number
    }
    kanal total
}

thee evens_upto(n) {
    na evens = []
    ozhugu i ul range(0, n + 1) {
        endral i % 2 == 0 {
            evens.push(i)
        }
    }
    kanal evens
}

